            (
                min(row["deadline"], now + self.lease_seconds),
                run_id,
                token,
                row["generation"],
                now,
                now,
            ),
        )
        if updated.rowcount != 1:
            raise DomainError("Worker lease is stale")
        return connection.execute("SELECT * FROM worker_runs WHERE id=?", (run_id,)).fetchone()

